package study
import "testing"
func clamp(n int) int {
    if n < 0 { return 0 }; if n > 10 { return 10 }; return n
}

func TestClamp(t *testing.T) {
    cases := []struct { name string; input, want int }{
        {"below", -1, 0}, {"inside", 7, 7}, {"above", 11, 10},
    }
    for _, tc := range cases {
        t.Run(tc.name, func(t *testing.T) {
            if got := clamp(tc.input); got != tc.want {
                t.Fatalf("input %d: got %d, want %d", tc.input, got, tc.want)
            }
        })
    }
}

